// ============================================
// VALIDATION INPUT - Dataset Generator
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required context fields ---
const userId = body.user_id || ctx.user_id;
const guildId = body.guild_id || ctx.guild_id;
const userRequest = body.user_request || ctx.user_request || '';

if (!userId) {
  errors.push('user_id requis');
}
if (!guildId) {
  errors.push('guild_id requis');
}
if (!userRequest) {
  errors.push('user_request requis');
}

// --- Required specific field ---
const domain = body.domain || ctx.domain;
if (!domain) {
  errors.push('domain requis');
}

// --- Optional fields with defaults ---
const categories = body.categories || ctx.categories || ['simple', 'ambigu', 'multi-etape', 'elliptique'];
const countPerCategory = body.count_per_category || ctx.count_per_category || 10;
const toolsFocus = body.tools_focus || ctx.tools_focus || [];
const language = body.language || ctx.language || 'fr';

// --- API keys - from body or env ---
const generatorModel = body.generator?.model || $env.MODEL_ANTHROPIC || 'claude-haiku-4-5-20251001';
const generatorKey = body.generator?.api_key || body.plugin_context?.api_keys?.anthropic || $env.ANTHROPIC_API_KEY;
const reviewerModel = body.reviewer?.model || $env.MODEL_OPENAI || 'gpt-4o-mini';
const reviewerKey = body.reviewer?.api_key || body.plugin_context?.api_keys?.openai || $env.OPENAI_API_KEY;

// --- Qdrant config ---
const qdrantHost = $env.QDRANT_SHARED_1_HOST || 'host3.local';
const qdrantPort = $env.QDRANT_SHARED_1_PORT || '20001';
const qdrantApiKey = $env.QDRANT_SHARED_1_API_KEY || '';
const qdrantCollection = 'tools_index';

if (!generatorKey) errors.push('Generator API key manquant');
if (!reviewerKey) errors.push('Reviewer API key manquant');

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

// --- Generate job ID ---
const now = new Date();
const timestamp = now.toISOString().replace(/[-:]/g, '').replace('T', '_').substring(0, 15);
const jobId = `dataset_${domain.replace(/\s+/g, '_')}_${timestamp}`;

return {
  valid: true,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now(),
  config: {
    jobId,
    domain,
    categories,
    countPerCategory,
    toolsFocus,
    language,
    generatorModel,
    generatorKey,
    reviewerModel,
    reviewerKey,
    qdrantUrl: `http://${qdrantHost}:${qdrantPort}`,
    qdrantApiKey,
    qdrantCollection
  },
  stats: {
    startedAt: now.toISOString()
  }
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

const qdrantResponse = $input.first().json;
const prevData = $('Validate Input').first().json;
const config = prevData.config;

if (qdrantResponse.error || !qdrantResponse.result?.points) {
  return [{
    json: {
      error: true,
      message: 'Erreur recuperation Qdrant: ' + (qdrantResponse.error?.message || 'Unknown'),
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request,
      startTime: prevData.startTime
    }
  }];
}

const points = qdrantResponse.result.points;
const toolsFocus = config.toolsFocus || [];

// Build tools reference for LLM prompt
let toolsReference = '';
const toolsList = [];

for (const p of points) {
  const pl = p.payload || {};
  const name = pl.name || pl.webhook_path || 'unknown';
  const webhookPath = pl.webhook_path || '';
  const description = pl.description || '';
  const keywords = (pl.keywords || []).slice(0, 8).join(', ');
  const operations = (pl.operations || []).map(op => `${op.id}(${op.type})`).join(', ');
  const useCases = (pl.use_cases || []).slice(0, 3).join('; ');

  toolsList.push(webhookPath || name);

  // Highlight focused tools
  const isFocused = toolsFocus.some(t => name.toLowerCase().includes(t.toLowerCase()) || webhookPath.toLowerCase().includes(t.toLowerCase()));
  const marker = isFocused ? ' [PRIORITAIRE]' : '';

  toolsReference += `\n### ${name}${marker}\n`;
  toolsReference += `- **webhook**: ${webhookPath}\n`;
  toolsReference += `- **description**: ${description}\n`;
  toolsReference += `- **keywords**: ${keywords}\n`;
  toolsReference += `- **operations**: ${operations}\n`;
  toolsReference += `- **use_cases**: ${useCases}\n`;
}

console.log(`[Dataset Generator] Loaded ${points.length} tools from Qdrant`);

// Prepare category items for loop
const categoryItems = config.categories.map(cat => ({
  json: {
    category: cat,
    config,
    toolsReference,
    toolsList,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request,
    startTime: prevData.startTime
  }
}));

return categoryItems;

const data = $input.first().json;
const config = data.config;
const category = data.category;
const toolsReference = data.toolsReference;
const userRequest = data.user_request;

// Inject user_request into the prompt for context
const prompt = `Tu es un generateur de dataset de test pour un systeme d'analyse d'intentions.

## Contexte de la demande utilisateur

**Demande originale:** ${userRequest}

## Ta mission

Generer ${config.countPerCategory} cas de test pour la categorie "${category}" dans le domaine "${config.domain}".

## Categories de test

### simple
Requetes avec une seule intention claire ou toutes les informations sont fournies.
- next_action_attendu = "search_tools" (toujours)

### ambigu
Requetes ou il manque des informations critiques ou references floues.
- MISSING_BLOCKING -> next_action = "ask_user"
- LOOKUP_REQUIRED -> next_action = "resolve_entities"

### multi-etape
Requetes impliquant plusieurs actions sequentielles (2-4 outils).
- Si step 1 executable -> next_action = "search_tools"
- Si step 1 bloque -> next_action = "ask_user"

### elliptique
Requetes referencant le contexte. TOUJOURS inclure [context: ...].

## Statuts des entites

- RESOLVED: Valeur fournie explicitement
- LOOKUP_REQUIRED: Prenom seul a chercher, fichier a chercher
- AMBIGUOUS: Plusieurs resultats possibles
- USER_CONFIRMATION_REQUIRED: Inference risquee
- MISSING_BLOCKING: Info indispensable absente

## Outils disponibles

${toolsReference}

## Format de sortie

Reponds UNIQUEMENT avec un tableau JSON:

\`\`\`json
[
  {
    "id": 1,
    "categorie": "${category}",
    "demande_utilisateur": "La requete en francais",
    "next_action_attendu": "ask_user|confirm_inference|disambiguate|resolve_entities|search_tools",
    "outils_obligatoires": "outil1,outil2",
    "entites_a_resoudre": "type:valeur->STATUT,type:valeur->STATUT",
    "missing_blocking": "champ1|champ2",
    "notes_testeur": "Explication du comportement attendu"
  }
]
\`\`\`

## Contraintes

1. Utilise UNIQUEMENT les outils de la liste
2. Demandes naturelles et variees
3. Coherence next_action / statuts entites
4. Pour elliptique, TOUJOURS [context: ...]
5. Langue: ${config.language}`;

const requestBody = {
  model: config.generatorModel,
  max_tokens: 4000,
  messages: [
    {
      role: 'user',
      content: prompt
    }
  ]
};

return [{
  json: {
    ...data,
    claudeRequestBody: requestBody
  }
}];

const input = $input.first().json;
const prevData = $('Prepare Claude Body').first().json;

if (input.error) {
  return [{
    json: {
      ...prevData,
      generatedCases: [],
      generatorError: input.error.message || 'Generator error',
      status: 'generator_failed'
    }
  }];
}

try {
  const content = input.content?.[0]?.text || '';

  // Extract JSON array from response
  const jsonMatch = content.match(/\[\s*\{[\s\S]*\}\s*\]/m);
  if (!jsonMatch) {
    return [{
      json: {
        ...prevData,
        generatedCases: [],
        generatorError: 'No JSON array found in response',
        status: 'generator_failed'
      }
    }];
  }

  const cases = JSON.parse(jsonMatch[0]);
  console.log(`[Dataset Generator] Generated ${cases.length} cases for category: ${prevData.category}`);

  return [{
    json: {
      ...prevData,
      generatedCases: cases,
      generatorUsage: input.usage || {},
      generatorResponse: content,
      status: 'generated'
    }
  }];
} catch (e) {
  return [{
    json: {
      ...prevData,
      generatedCases: [],
      generatorError: 'Parse error: ' + e.message,
      status: 'generator_failed'
    }
  }];
}

